const now = new Date();
const today = now.toISOString().slice(0, 10);
// 시간표를 읽지 못하면 기본 시간표로 넘어가지 않는다. 그 상태로 진행하면 실제와
// 다른 시간표로 출결을 기록하게 된다. 오류로 표시해 Slack 알림 후 중단시킨다.
let scheduleText = '';
let scheduleError = '';
try {
  // $binary는 Code 노드에서 정의되지 않는다(항목별 실행 모드 전용). 앞 노드의
  // 항목을 직접 집어야 한다. 실측으로 $binary가 undefined인 것을 확인했다.
  const incoming = $input.first().binary;
  if (incoming && incoming.data && incoming.data.data) {
    scheduleText = Buffer.from(incoming.data.data, 'base64').toString('utf8');
  } else {
    scheduleError = '시간표 문서를 읽지 못했습니다. 경로를 확인하세요.';
  }
} catch (error) {
  scheduleError = '시간표 문서를 여는 중 오류가 났습니다: ' + String(error).slice(0, 200);
}
const defaultPeriods = [
  { name: 'morning-study', start: '08:00', end: '08:40' },
  { name: 'period-1', start: '08:40', end: '10:10' },
  { name: 'period-2', start: '10:20', end: '11:50' },
  { name: 'period-3', start: '13:00', end: '14:30' },
  { name: 'period-4', start: '14:40', end: '16:10' },
  { name: 'period-5', start: '16:20', end: '17:50' },
  { name: 'night-period-1', start: '19:00', end: '20:30' },
  { name: 'night-period-2', start: '20:40', end: '22:00' }
];
const parsed = [];
// 구간 이름은 그 줄에서 끝난다. [^|]는 줄바꿈까지 삼켜서 표가 아닌 형식일 때
// 다음 줄을 이름에 붙이고 구간을 통째로 건너뛴다. 개행을 제외해 막는다.
const lineRegex = /\*\*(\d{2}:\d{2})\s*~\s*(\d{2}:\d{2})\*\*\s*\|\s*([^|\n\r]+)/g;
let match;
let index = 0;
while ((match = lineRegex.exec(scheduleText)) !== null) {
  const label = match[3].trim();
  if (!/(자습|교시|study|period)/i.test(label)) continue;
  parsed.push({ name: label || `period-${++index}`, start: match[1], end: match[2] });
}
if (!scheduleError && !parsed.length) {
  scheduleError = '시간표 문서에서 공부 시간 구간을 찾지 못했습니다. 형식을 확인하세요.';
}
const periods = parsed.length ? parsed : defaultPeriods;
function at(time) {
  const [hour, minute] = time.split(':').map(Number);
  const value = new Date(now);
  value.setHours(hour, minute, 0, 0);
  return value;
}
const active = periods.find((period) => now >= at(period.start) && now <= at(period.end));
const ended = periods.find((period) => {
  const end = at(period.end).getTime();
  return now.getTime() >= end && now.getTime() < end + 5 * 60 * 1000;
});
return [{ json: { today, periods, scheduleError, activePeriod: active || null, endedPeriod: ended || null, classroomId: $env.CLASSROOM_ID, classroomName: $env.CLASSROOM_NAME || $env.CLASSROOM_ID } }];

// 좌석 상태는 바로 앞 HTTP 응답에서, 시간표·강의실 정보는 Parse Schedule에서 가져온다.
// HTTP 응답이 $json을 통째로 덮어써서 Parse Schedule이 만든 today·classroomId가
// 여기까지 따라오지 않는다. 노드를 이름으로 직접 참조해야 한다.
const states = $input.first().json.states || [];
const input = $('Parse Schedule').first().json;
const workflowData = $getWorkflowStaticData('global');
workflowData.events = workflowData.events || [];
workflowData.lastState = workflowData.lastState || {};
const now = new Date().toISOString();
const period = input.activePeriod || input.endedPeriod || { name: 'manual-run' };
const meaningfulStates = new Set(['ABSENT', 'WRONG_SEAT', 'IN_CLASSROOM', 'UNKNOWN', 'PRESENT']);
const newEvents = [];
for (const state of states) {
  const studentId = state.student_id;
  const current = state.current_state || 'UNKNOWN';
  if (!studentId || !meaningfulStates.has(current)) continue;
  const last = workflowData.lastState[studentId];
  const changed = !last || last.state !== current;
  workflowData.lastState[studentId] = { state: current, at: now };
  if (!changed) continue;
  const seatNumber = state.assigned_seat_label || state.current_seat_label || state.assigned_seat_id || state.current_seat_id || '';
  const key = [input.today, input.classroomId, period.name, studentId, current, state.last_observed_at || now].join('|');
  if (workflowData.events.some((event) => event.key === key)) continue;
  const event = {
    key,
    period: period.name,
    observed_at: state.last_observed_at || now,
    seat_number: seatNumber,
    student_id: studentId,
    student_name: state.student_name,
    student_state: current
  };
  workflowData.events.push(event);
  newEvents.push(event);
}
const allEvents = workflowData.events.filter((event) => event.key && event.key.startsWith(input.today + '|' + input.classroomId + '|'));
const eventsBase64 = Buffer.from(JSON.stringify(allEvents), 'utf8').toString('base64');
const workbookPath = `RPAs/study-status-report/reports/study_status_${input.today}_${input.classroomId}.xlsx`;
const uploadTitle = `Study status - ${input.classroomName} ${input.today}`;
const uploadComment = `Study period finished. Period: ${(input.endedPeriod && input.endedPeriod.name) || period.name}`;
return [{ json: { ...input, newEvents, allEvents, eventsBase64, workbookPath, uploadTitle, uploadComment, shouldSendPeriodReport: Boolean(input.endedPeriod) } }];

const today = new Date().toISOString().slice(0, 10);
const workflowData = $getWorkflowStaticData('global');
const classroomId = $env.CLASSROOM_ID;
const classroomName = $env.CLASSROOM_NAME || classroomId;
const allEvents = (workflowData.events || []).filter((event) => event.key && event.key.startsWith(today + '|' + classroomId + '|'));
const eventsBase64 = Buffer.from(JSON.stringify(allEvents), 'utf8').toString('base64');
const workbookPath = `RPAs/study-status-report/reports/study_status_${today}_${classroomId}.xlsx`;
const uploadTitle = `Daily study report - ${classroomName} ${today}`;
const uploadComment = 'Daily self-study report. See the daily report sheet for leave-rate statistics.';
return [{ json: { today, classroomId, classroomName, allEvents, eventsBase64, workbookPath, uploadTitle, uploadComment } }];
